/* Heatwave Lab window. Reads data/e003-heatwave-lab-v1.json (generated by
   scripts/build_heatwave_lab_data.py from committed e003 results) and lets the
   reader drag the forecast quantile a packing controller plans around, then
   replays that simulated episode: site power against the cap, racks warming,
   and the counters for that choice. Nothing here computes a result; every
   number shown is read from the data file. Results not in yet say so. */
(function (root) {
  "use strict";
  var NS = "http://www.w3.org/2000/svg";
  var DATA_URL = "data/e003-heatwave-lab-v1.json";

  function h(tag, attrs, kids) {
    var n = document.createElement(tag);
    for (var k in attrs || {}) {
      if (k === "text") n.textContent = attrs[k];
      else if (k.slice(0, 2) === "on") n.addEventListener(k.slice(2), attrs[k]);
      else if (attrs[k] !== null && attrs[k] !== undefined) n.setAttribute(k, attrs[k]);
    }
    (kids || []).forEach(function (c) { if (c) n.append(c); });
    return n;
  }
  function s(tag, attrs, kids) {
    var n = document.createElementNS(NS, tag);
    for (var k in attrs || {}) if (attrs[k] !== null && attrs[k] !== undefined) n.setAttribute(k, attrs[k]);
    (kids || []).forEach(function (c) { if (c) n.append(c); });
    return n;
  }
  function fmt(x, d) {
    if (x === null || x === undefined || isNaN(x)) return "n/a";
    return Number(x).toLocaleString("en-US", { minimumFractionDigits: d || 0, maximumFractionDigits: d || 0 });
  }
  function pct(x, d) { return x === null || x === undefined ? "n/a" : fmt(100 * x, d === undefined ? 0 : d) + "%"; }
  function ci(m, d) {
    if (!m) return "n/a";
    return fmt(m.mean, d) + " [" + fmt(m.lo, d) + ", " + fmt(m.hi, d) + "]";
  }
  function pending(text) { return h("p", { class: "hwl-pending", text: text || "Result pending." }); }

  function levelLabel(q) {
    var p = Math.round(q * 100);
    var suf = p % 10 === 1 && p !== 11 ? "st" : p % 10 === 2 && p !== 12 ? "nd" : p % 10 === 3 && p !== 13 ? "rd" : "th";
    return p + suf;
  }

  /* ---------------- packing ---------------- */
  function packingPane(P) {
    if (!P || P.status !== "ready") return pending("The packing result is not in yet.");
    var levels = P.quantile_levels;
    var penalties = P.penalties_usd_per_kwh;
    var tr = P.trace;
    var state = { i: levels.indexOf(0.9) >= 0 ? levels.indexOf(0.9) : 18, pen: penalties[2] || penalties[0], t: 0, playing: false };
    var nT = tr.runs.reactive.site_power_kw.length;

    var allTemps = [];
    Object.keys(tr.runs).forEach(function (k) {
      tr.runs[k].rack_max_gpu_c.forEach(function (row) { row.forEach(function (v) { if (v !== null) allTemps.push(v); }); });
    });
    var tMin = Math.min.apply(null, allTemps), tMax = Math.max.apply(null, allTemps);
    var pMax = 0;
    Object.keys(tr.runs).forEach(function (k) {
      tr.runs[k].site_power_kw.forEach(function (row) { row.forEach(function (v) { if (v > pMax) pMax = v; }); });
    });
    pMax = Math.max(pMax, Math.max.apply(null, tr.site_caps_kw)) * 1.05;

    var label = h("label", { class: "hwl-label", for: "hwl-q" });
    var slider = h("input", { type: "range", id: "hwl-q", min: "0", max: String(levels.length - 1), step: "1", value: String(state.i),
      "aria-describedby": "hwl-q-help" });
    var penSel = h("select", { id: "hwl-pen", "aria-label": "Price of going over the cap" },
      penalties.map(function (p) { return h("option", { value: String(p), text: "$" + p + " per kWh over the cap" }); }));
    penSel.value = String(state.pen);
    var play = h("button", { type: "button", class: "hwl-btn", text: "Play" });

    var W = 640, H = 220, L = 46, R = 10, T = 12, B = 30;
    var svg = s("svg", { viewBox: "0 0 " + W + " " + H, class: "hwl-chart", role: "img",
      "aria-label": "Site power over the scored window against each site's power cap" });
    function x(i) { return L + (W - L - R) * i / (nT - 1); }
    function y(v) { return T + (H - T - B) * (1 - v / pMax); }
    for (var g = 0; g <= 4; g++) {
      var gv = pMax * g / 4;
      svg.append(s("line", { x1: L, x2: W - R, y1: y(gv), y2: y(gv), class: "hwl-grid" }));
      var tx = s("text", { x: L - 6, y: y(gv) + 4, class: "hwl-axis", "text-anchor": "end" }); tx.textContent = fmt(gv); svg.append(tx);
    }
    var xl = s("text", { x: W - R, y: H - 6, class: "hwl-axis", "text-anchor": "end" });
    xl.textContent = "hours into the scored window, " + fmt(nT * tr.bin_s / 3600) + " h"; svg.append(xl);
    var yl = s("text", { x: 4, y: 10, class: "hwl-axis" }); yl.textContent = "kW"; svg.append(yl);
    var caps = tr.site_caps_kw.map(function (c, k) {
      var ln = s("line", { x1: L, x2: W - R, y1: y(c), y2: y(c), class: "hwl-cap hwl-s" + k });
      svg.append(ln);
      return ln;
    });
    var lines = tr.site_ids.map(function (sid, k) { var p = s("polyline", { class: "hwl-line hwl-s" + k, fill: "none" }); svg.append(p); return p; });
    var cursor = s("line", { y1: T, y2: H - B, class: "hwl-cursor" }); svg.append(cursor);

    var racks = h("div", { class: "hwl-racks", role: "group", "aria-label": "Racks, colored by their hottest GPU" });
    var rackCells = tr.rack_ids.map(function (rid) {
      var temp = h("span", { class: "hwl-rack-temp" });
      var cell = h("div", { class: "hwl-rack" }, [h("span", { class: "hwl-rack-id", text: rid }), temp]);
      racks.append(cell);
      return { cell: cell, temp: temp };
    });

    var counters = h("table", { class: "hwl-table" });
    var best = h("p", { class: "hwl-note" });

    function policyId() { return "timestral-5M/q" + String(levels[state.i]).replace(/^0\./, "0."); }
    function key(q) {
      var str = String(q);
      return "timestral-5M/q" + str;
    }
    function heat(v) {
      if (v === null || v === undefined) return "var(--chrome-well)";
      var f = Math.max(0, Math.min(1, (v - tMin) / Math.max(1e-6, tMax - tMin)));
      return "oklch(" + (0.86 - 0.28 * f).toFixed(3) + " " + (0.04 + 0.16 * f).toFixed(3) + " " + (95 - 70 * f).toFixed(1) + ")";
    }
    function draw() {
      var q = levels[state.i];
      label.textContent = "Plan around the " + levelLabel(q) + " percentile of the Timestral power forecast";
      var run = tr.runs[key(q)];
      lines.forEach(function (ln, k) {
        if (!run) { ln.setAttribute("points", ""); return; }
        ln.setAttribute("points", run.site_power_kw.map(function (row, i) { return x(i).toFixed(1) + "," + y(row[k]).toFixed(1); }).join(" "));
      });
      cursor.setAttribute("x1", x(state.t)); cursor.setAttribute("x2", x(state.t));
      rackCells.forEach(function (rc, k) {
        var v = run ? run.rack_max_gpu_c[state.t][k] : null;
        rc.cell.style.background = heat(v);
        rc.temp.textContent = v === null || v === undefined ? "off" : fmt(v, 1) + " °C";
      });
      var pen = String(state.pen);
      var rows = [["Plan around the " + levelLabel(q) + " percentile", P.policies[key(q)]],
        ["React to measured power", P.policies.reactive],
        ["Learned quantile choice", P.policies["timestral-5M/learned@" + pen]]];
      counters.replaceChildren(h("thead", {}, [h("tr", {}, ["policy", "GPU-hours delivered", "energy over the cap (kWh)", "intervals over the cap", "net value at this price ($)"].map(function (t) { return h("th", { text: t }); }))]));
      var tb = h("tbody");
      rows.forEach(function (r) {
        var m = r[1];
        tb.append(h("tr", {}, [h("td", { text: r[0] }), h("td", { text: m ? ci(m.gpu_hours, 0) : "n/a" }),
          h("td", { text: m ? ci(m.energy_above_cap_kwh, 1) : "n/a" }), h("td", { text: m ? pct(m.violation_rate.mean) : "n/a" }),
          h("td", { text: m && m.net_value_usd && m.net_value_usd[pen] ? ci(m.net_value_usd[pen], 0) : "n/a" })]));
      });
      counters.append(tb);
      var b = P.best_fixed_by_penalty[pen];
      best.textContent = "At $" + pen + " per kWh over the cap, the fixed choice with the most net value on the test seeds was " +
        (b ? b.replace("/q", ", planning at the ") .replace(/(0\.\d+|\d+)$/, function (m) { return levelLabel(Number(m)) + " percentile"; }) : "n/a") + ".";
    }
    var timer = null;
    function stepPlay() {
      state.t = (state.t + 1) % nT;
      draw();
    }
    play.addEventListener("click", function () {
      state.playing = !state.playing;
      play.textContent = state.playing ? "Pause" : "Play";
      if (state.playing) timer = root.setInterval(stepPlay, 120); else root.clearInterval(timer);
    });
    slider.addEventListener("input", function () { state.i = Number(slider.value); draw(); });
    penSel.addEventListener("change", function () { state.pen = Number(penSel.value); draw(); });
    draw();
    return h("div", { class: "hwl-pane" }, [
      h("p", { class: "hwl-caption", text: "Simulated. Two sites, test seed " + tr.seed + " shown; the table gives means and 95% intervals over " +
        P.test_seeds.length + " test seeds. Planning lower packs more jobs and goes over the cap more often." }),
      h("div", { class: "hwl-controls" }, [label, slider, h("span", { id: "hwl-q-help", class: "hwl-help", text: "1st to 99th percentile, 21 steps" }), penSel, play]),
      svg, racks, counters, best,
    ]);
  }

  /* ---------------- outage ---------------- */
  function outagePane(O) {
    if (!O || O.status !== "ready") return pending();
    var box = h("div", { class: "hwl-pane" }, [h("p", { class: "hwl-caption", text: "Simulated. Warn before trouble, checkpoint early, then move or pause the work. Means over the held-out seeds." })]);
    ["v2", "v1"].forEach(function (ver) {
      var V = O.versions[ver];
      box.append(h("h3", { class: "hwl-h", text: ver === "v2" ? "With each GPU's own temperature as a warning sign" : "First version (rack-level warning signs)" }));
      if (!V || V.status !== "ready") { box.append(pending()); return; }
      var t = h("table", { class: "hwl-table" }, [h("thead", {}, [h("tr", {}, ["policy", "useful GPU-hours", "GPU-hours lost to faults", "events warned in time", "false alarms per day"].map(function (x) { return h("th", { text: x }); }))])]);
      var tb = h("tbody");
      Object.keys(V.policies).forEach(function (k) {
        var p = V.policies[k];
        tb.append(h("tr", {}, [h("td", { text: p.label }), h("td", { text: fmt(p.useful_gpu_h, 0) }), h("td", { text: fmt(p.lost_gpu_h, 1) }),
          h("td", { text: p.recall === null ? "n/a" : pct(p.recall) }), h("td", { text: p.false_alarms_per_day === null ? "n/a" : fmt(p.false_alarms_per_day, 1) })]));
      });
      t.append(tb);
      box.append(t);
    });
    return box;
  }

  /* ---------------- timing ---------------- */
  var NAMES = { no_shift: "no shifting", reactive: "react to today's price", seasonal_naive_24: "yesterday's prices", ets_24: "ETS",
    arima_seasonal: "ARIMA", timestral_28M: "Timestral 28M", perfect: "perfect foresight", offline_optimum: "best possible schedule" };
  function timingPane(C) {
    if (!C || C.status !== "ready") return pending();
    var pair = "caiso";
    var holder = h("div");
    var seg = h("div", { class: "hwl-tabs", role: "tablist", "aria-label": "Grid region" });
    function render() {
      var P = C.pairs[pair];
      var pols = Object.keys(P.curves);
      var xs = [], ys = [];
      pols.forEach(function (k) { xs = xs.concat(P.curves[k].electricity_usd_per_mtoken); ys = ys.concat(P.curves[k].co2_g_per_mtoken); });
      var x0 = Math.min.apply(null, xs), x1 = Math.max.apply(null, xs), y0 = Math.min.apply(null, ys), y1 = Math.max.apply(null, ys);
      var W = 640, H = 260, L = 70, R = 150, T = 12, B = 36;
      function X(v) { return L + (W - L - R) * (v - x0) / Math.max(1e-12, x1 - x0); }
      function Y(v) { return T + (H - T - B) * (1 - (v - y0) / Math.max(1e-12, y1 - y0)); }
      var svg = s("svg", { viewBox: "0 0 " + W + " " + H, class: "hwl-chart", role: "img", "aria-label": "Electricity dollars per million tokens against grams of CO2 per million tokens, for each scheduling policy" });
      var xl = s("text", { x: L, y: H - 6, class: "hwl-axis" }); xl.textContent = "electricity, $ per million tokens"; svg.append(xl);
      var yl = s("text", { x: 4, y: 10, class: "hwl-axis" }); yl.textContent = "g CO2 per million tokens"; svg.append(yl);
      pols.forEach(function (k, j) {
        var c = P.curves[k];
        var pts = c.electricity_usd_per_mtoken.map(function (v, i) { return X(v).toFixed(1) + "," + Y(c.co2_g_per_mtoken[i]).toFixed(1); });
        svg.append(s("polyline", { points: pts.join(" "), class: "hwl-pareto hwl-p" + (j % 8), fill: "none" }));
        var last = pts.length - 1;
        var t = s("text", { x: W - R + 6, y: T + 14 + j * 16, class: "hwl-axis hwl-p" + (j % 8) + "-t" }); t.textContent = NAMES[k] || k; svg.append(t);
      });
      var mid = P.curves.timestral_28M ? Math.floor(P.curves.timestral_28M.lambda.length / 2) : null;
      var txt = mid === null ? "" : "Halfway between cheapest and cleanest, Timestral 28M cuts the electricity cost of the flexible work by " +
        fmt(P.curves.timestral_28M.saving_pct_electricity[mid], 1) + "% and its carbon by " + fmt(P.curves.timestral_28M.saving_pct_co2[mid], 1) +
        "%; the whole cost per token moves by " + fmt(P.curves.timestral_28M.saving_pct_total[mid], 2) + "%.";
      holder.replaceChildren(svg, h("p", { class: "hwl-note", text: txt }));
    }
    ["caiso", "de"].forEach(function (p) {
      var b = h("button", { type: "button", class: "hwl-btn", role: "tab", text: p === "caiso" ? "California (CAISO)" : "Germany (DE-LU)" });
      b.addEventListener("click", function () { pair = p; render(); });
      seg.append(b);
    });
    render();
    return h("div", { class: "hwl-pane" }, [
      h("p", { class: "hwl-caption", text: "Public day-ahead prices and carbon intensity, last 26 weeks held out; 30% of the work may wait up to 24 hours. Each line sweeps from cheapest to cleanest." }),
      seg, holder]);
  }

  function mount(el) {
    el.replaceChildren(h("p", { class: "hwl-pending", text: "Loading the Heatwave results." }));
    fetch(DATA_URL).then(function (r) { return r.json(); }).then(function (D) {
      var panes = { packing: packingPane(D.packing), outage: outagePane(D.outage), timing: timingPane(D.cost) };
      var names = { packing: "Pack jobs under a cap", outage: "Outages", timing: "Cheaper, cleaner hours" };
      var tabs = h("div", { class: "hwl-tabs", role: "tablist", "aria-label": "Heatwave experiments" });
      var body = h("div", { class: "hwl-body" });
      function show(k) {
        body.replaceChildren(panes[k]);
        Array.prototype.forEach.call(tabs.children, function (b) { b.setAttribute("aria-selected", String(b.dataset.k === k)); });
      }
      Object.keys(panes).forEach(function (k) {
        var b = h("button", { type: "button", role: "tab", class: "hwl-btn", "data-k": k, text: names[k] });
        b.addEventListener("click", function () { show(k); });
        tabs.append(b);
      });
      el.replaceChildren(h("div", { class: "hwl" }, [tabs, body]));
      show("packing");
    }).catch(function () {
      el.replaceChildren(h("p", { class: "hwl-pending", text: "The Heatwave data file could not be loaded." }));
    });
  }

  root.GPUStackHeatwave = { mount: mount };
})(typeof window !== "undefined" ? window : globalThis);
